package com.otaviobarreto.pokedex.data

enum class JourneyChallengeKind(val label:String){ GYM("Ginásio"), TITAN("Titã"), STAR("Team Star"), STORY("História"), POSTGAME("Pós-jogo"), DLC("DLC"), EPILOGUE("Epílogo") }

data class JourneyStep(
    val id:String,
    val order:Int,
    val title:String,
    val subtitle:String,
    val levelLabel:String,
    val kind:JourneyChallengeKind,
    val typeLabel:String,
    val location:String,
    val note:String = "",
    val imageUrl:String? = null
)

object JourneyCatalog {
    fun routeLabel(game:String):String = when(game){
        "Scarlet / Violet" -> "Campanha + pós-jogo + DLC · rota completa"
        "Pokémon Legends: Z-A" -> "Z-A Royale + Rogue Megas + pós-jogo + Mega Dimension"
        "Legends Arceus" -> "Survey Corps + Nobres + espaço-tempo + pós-jogo + Daybreak"
        "Sword / Shield" -> "Gym Challenge + Champion Cup + pós-jogo + Isle of Armor + Crown Tundra"
        "Brilliant Diamond / Shining Pearl" -> "Sinnoh + 8 ginásios + Team Galactic + Liga + pós-jogo"
        "Let's Go Pikachu / Eevee" -> "Kanto + 8 ginásios + Team Rocket + Liga + Master Trainers"
        "FireRed / LeafGreen" -> "Kanto + 8 ginásios + Team Rocket + Sevii Islands + Liga + pós-jogo"
        else -> "Rota de campanha"
    }

    fun steps(game:String):List<JourneyStep> = when(game){
        "Scarlet / Violet" -> scarletViolet
        "Pokémon Legends: Z-A" -> legendsZa
        "Legends Arceus" -> legendsArceus
        "Sword / Shield" -> swordShield
        "Brilliant Diamond / Shining Pearl" -> brilliantDiamondShiningPearl
        "Let's Go Pikachu / Eevee" -> letsGoPikachuEevee
        "FireRed / LeafGreen" -> fireRedLeafGreen
        else -> emptyList()
    }

